		case "chevron.up": self = .chevronUp
		case "chevron.down": self = .chevronDown
		case "xmark": self = .close
		case "plus": self = .plus
		case "checkmark": self = .check
		case "folder": self = .folder
		case "folder.badge.plus": self = .folderAdd
		case "tray.full", "square.stack": self = .stack
		case "pin", "pin.fill": self = .pin
		case "star", "star.fill": self = .star
		case "trash": self = .trash
		case "square.and.arrow.up": self = .share
		case "number": self = .hash
		case "info.circle": self = .info
		case "exclamationmark.triangle": self = .warning
		case "arrow.clockwise": self = .rebuild
		case "arrow.uturn.backward": self = .undo
		case "arrow.uturn.forward": self = .redo
		case "ellipsis": self = .more
		case "lock": self = .lock
		case "bolt.fill", "bolt": self = .bolt
		case "book.closed", "book": self = .book
		case "briefcase": self = .briefcase
		case "flask": self = .flask
		case "house": self = .house
		case "lightbulb": self = .lightbulb
		case "pencil": self = .pencil
		case "calendar": self = .calendar
		case "heart": self = .heart
		case "gearshape": self = .gear
		case "doc.on.doc": self = .copy
		case "text.bubble": self = .note
		default: return nil
		}
	}

