				InkTerminal(x: 16, y: 3.5, dx: 1, dy: 0),
				InkTerminal(x: 12, y: 21.5, dx: 0, dy: 1),
			]
		case .trash:
			return [
				InkTerminal(x: 3.5, y: 6.5, dx: -1, dy: 0),
				InkTerminal(x: 20.5, y: 6.5, dx: 1, dy: 0),
				InkTerminal(x: 10.25, y: 10, dx: 0, dy: -1),
				InkTerminal(x: 10.25, y: 17.5, dx: 0, dy: 1),
				InkTerminal(x: 13.75, y: 10, dx: 0, dy: -1),
				InkTerminal(x: 13.75, y: 17.5, dx: 0, dy: 1),
			]
		case .share:
			return [
				InkTerminal(x: 12, y: 14.5, dx: 0, dy: 1),
				InkTerminal(x: 8, y: 7, dx: -0.707, dy: 0.707),
				InkTerminal(x: 16, y: 7, dx: 0.707, dy: 0.707),
				InkTerminal(x: 8.5, y: 9.75, dx: 1, dy: 0),
				InkTerminal(x: 15.5, y: 9.75, dx: -1, dy: 0),
			]
		case .hash:
			return [
				InkTerminal(x: 10, y: 3.5, dx: 0.102, dy: -0.995),
				InkTerminal(x: 8.25, y: 20.5, dx: -0.102, dy: 0.995),
				InkTerminal(x: 15.75, y: 3.5, dx: 0.102, dy: -0.995),
				InkTerminal(x: 14, y: 20.5, dx: -0.102, dy: 0.995),
				InkTerminal(x: 4.5, y: 9, dx: -1, dy: 0),
				InkTerminal(x: 20, y: 9, dx: 1, dy: 0),
				InkTerminal(x: 4, y: 15, dx: -1, dy: 0),
				InkTerminal(x: 19.5, y: 15, dx: 1, dy: 0),
			]
		case .info:
			return [
				InkTerminal(x: 12, y: 10.75, dx: 0, dy: -1),
				InkTerminal(x: 12, y: 17.25, dx: 0, dy: 1),
			]
		case .warning:
			return [
				InkTerminal(x: 12, y: 9, dx: 0, dy: -1),
				InkTerminal(x: 12, y: 14, dx: 0, dy: 1),
			]
		case .rebuild:
			return [
				InkTerminal(x: 19.75, y: 12.5, dx: 0, dy: -1),
				InkTerminal(x: 12.679, y: 1.509, dx: -0.47, dy: -0.883),
				InkTerminal(x: 10.756, y: 6.791, dx: -0.927, dy: 0.375),
			]
		case .undo:
			return [
				InkTerminal(x: 9, y: 4.5, dx: 0.707, dy: -0.707),
				InkTerminal(x: 9, y: 13.5, dx: 0.707, dy: 0.707),
				InkTerminal(x: 11, y: 20, dx: -1, dy: 0),
			]
		case .redo:
			return [
				InkTerminal(x: 15, y: 4.5, dx: -0.707, dy: -0.707),
				InkTerminal(x: 15, y: 13.5, dx: -0.707, dy: 0.707),
				InkTerminal(x: 13, y: 20, dx: 1, dy: 0),
			]
		case .flask:
			return [
				InkTerminal(x: 8.25, y: 3, dx: -1, dy: 0),
				InkTerminal(x: 15.75, y: 3, dx: 1, dy: 0),
			]
		case .house:
			return [
				InkTerminal(x: 2.5, y: 11.5, dx: -0.765, dy: 0.644),
				InkTerminal(x: 21.5, y: 11.5, dx: 0.765, dy: 0.644),
			]
		case .lightbulb:
			return [
				InkTerminal(x: 9, y: 18.75, dx: -1, dy: 0),
				InkTerminal(x: 15, y: 18.75, dx: 1, dy: 0),
			]
		case .calendar:
			return [
				InkTerminal(x: 8, y: 2.5, dx: 0, dy: -1),
				InkTerminal(x: 8, y: 7.5, dx: 0, dy: 1),
				InkTerminal(x: 16, y: 2.5, dx: 0, dy: -1),
				InkTerminal(x: 16, y: 7.5, dx: 0, dy: 1),
			]
		case .copy:
			return [
				InkTerminal(x: 4, y: 16.5, dx: 0, dy: 1),
			]
		case .note:
			return [
				InkTerminal(x: 7, y: 8, dx: -1, dy: 0),
				InkTerminal(x: 17, y: 8, dx: 1, dy: 0),
				InkTerminal(x: 7, y: 11.75, dx: -1, dy: 0),
				InkTerminal(x: 13.5, y: 11.75, dx: 1, dy: 0),
			]
		default:
			return []
		}
	}
}
